<p class="eyebrow">Administration</p><h1>Platform control room</h1><div class="grid three"><article class="metric"><span>Total users</span><strong><?= e($metrics['users']??0) ?></strong></article><article class="metric"><span>Active users</span><strong><?= e($metrics['active']??0) ?></strong></article><article class="metric"><span>Suspended users</span><strong><?= e($metrics['suspended']??0) ?></strong></article><article class="metric"><span>Restricted users</span><strong><?= e($metrics['restricted']??0) ?></strong></article><article class="metric"><span>Global users</span><strong><?= e($metrics['global']??0) ?></strong></article><article class="metric"><span>Country Packs</span><strong><?= e($metrics['enabled_countries']??0) ?> enabled</strong></article></div><section class="card"><h2>Recent registrations</h2><div class="table-wrap"><table><thead><tr><th>User</th><th>Email</th><th>Registered</th></tr></thead><tbody><?php foreach($recent??[] as $user):?><tr><td><?= e($user['first_name'].' '.$user['last_name']) ?></td><td><?= e($user['email']) ?></td><td><?= e($user['created_at']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
